bandwidth = value["PixelBandwidth"].dropna()
if len(bandwidth) > 0:
    bw = bandwidth.iloc[0]
    manufacturer = value["Manufacturer"].iloc[0].upper() if "Manufacturer" in value.columns and not value["Manufacturer"].isna().all() else ""

    # Vendor-specific bandwidth targets from Table E1
    if "SIEMENS" in manufacturer:
        target_bw = 1800
        tolerance = 300
        if abs(bw - target_bw) > tolerance * 2:
            raise ValidationWarning(f"PixelBandwidth should be ~{target_bw} Hz/px for Siemens. Found {bw} Hz/px.")
    elif "PHILIPS" in manufacturer:
        target_bw = 5800
        tolerance = 1000
        if abs(bw - target_bw) > tolerance * 2:
            raise ValidationWarning(f"PixelBandwidth should be ~{target_bw} Hz/px for Philips. Found {bw} Hz/px.")
    elif "GE" in manufacturer or "GENERAL ELECTRIC" in manufacturer:
        target_bw = 976
        tolerance = 200
        if abs(bw - target_bw) > tolerance * 2:
            raise ValidationWarning(f"PixelBandwidth should be ~{target_bw} Hz/px for GE. Found {bw} Hz/px.")
    else:
        # Unknown vendor - just check reasonable range
        if bw < 500 or bw > 7000:
            raise ValidationWarning(f"PixelBandwidth {bw} Hz/px outside typical range for WB-DWI.")
